	analyzer.scopes.Define("x", sym)

	// Analyze identifier
	id := &ast.Identifier{Name: "x", Token: lexer.Token{Pos: lexer.Position{Line: 1, Column: 1}}}
	resultType := analyzer.analyzeIdentifier(id)

	if resultType.String() != "Int64" {
