	reg := types.NewRegistry()
	hier := types.NewHierarchy(reg)
	analyzer := NewAnalyzer(reg, hier)

	// Create Int64 + Int64
	binop := &ast.BinaryOp{
		Left:  &ast.Literal{Token: lexer.Token{Type: lexer.TokenInteger}},
		Op:    lexer.TokenPlus,
		Right: &ast.Literal{Token: lexer.Token{Type: lexer.TokenInteger}},
