	reg := types.NewRegistry()
	hier := types.NewHierarchy(reg)
	analyzer := NewAnalyzer(reg, hier)

	tests := []struct {
		tok      lexer.TokenType
		expected string
	}{
		{lexer.TokenPlus, "+"},
