		if result != test.expected {
			t.Errorf("getOperatorName(%v) = %s, want %s",
				test.tok, result, test.expected)
		}
	}
}

func BenchmarkAnalyzeSimple(b *testing.B) {
	source := `x = 1`

	reg := types.NewRegistry()
	hier := types.NewHierarchy(reg)

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
