}

// ConstDecl - 상수 선언 (const x = 5)
type ConstDecl struct {
	Name  string
	Type  string
	Value Expr
	Const lexer.Token
}

func (c *ConstDecl) node() {}
func (c *ConstDecl) stmt() {}
func (c *ConstDecl) String() string {
	return fmt.Sprintf("const %s = %s", c.Name, c.Value)
}

// FunctionDecl - 함수 선언
type FunctionDecl struct {
	Name       string
	Parameters []*Parameter
	ReturnType string // optional
	Body       []Stmt
	Function   lexer.Token
}

func (f *FunctionDecl) node() {}
func (f *FunctionDecl) stmt() {}
func (f *FunctionDecl) String() string {
	return fmt.Sprintf("function %s(...)", f.Name)
}

// Parameter - 함수 매개변수
type Parameter struct {
	Name     string
	Type     string    // optional
	Default  Expr      // optional
	Variadic bool      // ... 마킹
}

// StructDecl - 구조체 선언
type StructDecl struct {
	Name      string
	IsMutable bool
	Fields    []*StructField
	Struct    lexer.Token
}

func (s *StructDecl) node() {}
func (s *StructDecl) stmt() {}
func (s *StructDecl) String() string {
	return fmt.Sprintf("struct %s", s.Name)
}

// StructField - 구조체 필드
type StructField struct {
	Name    string
	Type    string
	Default Expr // optional
}

// IfStmt - if 문
type IfStmt struct {
	Condition Expr
	Then      []Stmt
	ElseIfs   []*ElseIfClause
	Else      []Stmt // nil if no else
	If        lexer.Token
}

func (i *IfStmt) node() {}
func (i *IfStmt) stmt() {}
func (i *IfStmt) String() string {
	return "if ..."
}

// ElseIfClause - elseif 절
type ElseIfClause struct {
	Condition Expr
	Body      []Stmt
	ElseIf    lexer.Token
}

// WhileStmt - while 루프
type WhileStmt struct {
	Condition Expr
	Body      []Stmt
	While     lexer.Token
}

func (w *WhileStmt) node() {}
func (w *WhileStmt) stmt() {}
func (w *WhileStmt) String() string {
	return "while ..."
}

// ForStmt - for 루프
type ForStmt struct {
	Variable string  // loop variable
	Iterator Expr    // iterable expression
	Body     []Stmt
	For      lexer.Token
}

func (f *ForStmt) node() {}
func (f *ForStmt) stmt() {}
func (f *ForStmt) String() string {
	return fmt.Sprintf("for %s in ...", f.Variable)
}

// ReturnStmt - return 문
type ReturnStmt struct {
	Value  Expr // nil for bare return
	Return lexer.Token
}

func (r *ReturnStmt) node() {}
func (r *ReturnStmt) stmt() {}
func (r *ReturnStmt) String() string {
	return "return ..."
}

// BreakStmt - break 문
type BreakStmt struct {
	Break lexer.Token
}

func (b *BreakStmt) node() {}
func (b *BreakStmt) stmt() {}
func (b *BreakStmt) String() string {
	return "break"
}

// ContinueStmt - continue 문
type ContinueStmt struct {
	Continue lexer.Token
}

func (c *ContinueStmt) node() {}
func (c *ContinueStmt) stmt() {}
func (c *ContinueStmt) String() string {
	return "continue"
}

// TryStmt - try-catch-finally 문
type TryStmt struct {
	Try     []Stmt
	Catches []*CatchClause
	Finally []Stmt // optional
	Try_    lexer.Token
}

func (t *TryStmt) node() {}
func (t *TryStmt) stmt() {}
func (t *TryStmt) String() string {
	return "try ..."
}

// CatchClause - catch 절
type CatchClause struct {
	ExceptionType string // optional (e.g., "DomainError")
	Variable      string // variable name (optional, e.g., e)
	Body          []Stmt
	Catch         lexer.Token
}

// Program - 프로그램 (최상위 노드)
type Program struct {
	Statements []Stmt
}

func (p *Program) node() {}
func (p *Program) String() string {
	return fmt.Sprintf("Program(%d statements)", len(p.Statements))
}

